import { IS_NON_DIMENSIONAL } from '../constants';

let runtimeOptions;

/**
 * Coordinates DOM property application, style writes, listener binding,
 * child placement, root render setup and compat prop rewriting.
 * @constructor
 */
export function PropertyHost() {
	this._propFrames = [];
	this._styleFrames = [];
	this._listenerFrames = [];
	this._childFrames = [];
	this._compatFrames = [];
	this._rootFrames = [];
}

PropertyHost.prototype.bindRuntime = function(options) {
	runtimeOptions = options;
	if (options) {
		options._propertyHost = this;
	}
};

PropertyHost.prototype.currentPropFrame = function() {
	let frames = this._propFrames;
	return frames.length ? frames[frames.length - 1] : null;
};

PropertyHost.prototype.pushPropFrame = function(dom, name, value, oldValue, isSvg) {
	let frame = {
		dom: dom,
		name: name,
		value: value,
		oldValue: oldValue,
		isSvg: isSvg
	};
	this._propFrames.push(frame);
	return this.currentPropFrame();
};

PropertyHost.prototype.popPropFrame = function() {
	if (this._propFrames.length) {
		this._propFrames.pop();
	}
	return (this._propFrames.length ? this._propFrames[this._propFrames.length - 1] : null);
};

/**
 * Diff the old and new properties of a VNode and apply changes to the DOM node
 */
PropertyHost.prototype.diffProps = function(dom, newProps, oldProps, isSvg, hydrate) {
	this.pushPropFrame(dom, null, newProps, oldProps, isSvg);
	try {
		let active = this._propFrames[this._propFrames.length - 1];
		active.dom = dom;
		active.value = newProps;
		active.oldValue = oldProps;
		active.isSvg = isSvg;
		let i;
		for (i in oldProps) {
			if (this.shouldSkipOldProp(i, newProps)) {
				continue;
			}
			this.setProperty(dom, i, null, oldProps[i], isSvg);
		}

		for (i in newProps) {
			if (this.shouldSkipNewProp(i, newProps, oldProps, hydrate)) {
				continue;
			}
			this.setProperty(dom, i, newProps[i], oldProps[i], isSvg);
		}
	} finally {
		this.popPropFrame();
	}
};

PropertyHost.prototype.shouldSkipOldProp = function(name, newProps) {
	let frame = (this._propFrames.length ? this._propFrames[this._propFrames.length - 1] : null);
	if (frame) {
		frame.name = name;
	}
	if (name === 'children' || name === 'key') {
		return true;
	}
	if (name in newProps) {
		return true;
	}
	return false;
};

PropertyHost.prototype.shouldSkipNewProp = function(name, newProps, oldProps, hydrate) {
	let frame = (this._propFrames.length ? this._propFrames[this._propFrames.length - 1] : null);
	if (frame) {
		frame.name = name;
		frame.value = newProps[name];
	}
	if (hydrate && typeof newProps[name] != 'function') {
		return true;
	}
	if (name === 'children' || name === 'key' || name === 'value' || name === 'checked') {
		return true;
	}
	if (oldProps[name] === newProps[name]) {
		return true;
	}
	return false;
};

/**
 * Set a property value on a DOM node
 */
PropertyHost.prototype.setProperty = function(dom, name, value, oldValue, isSvg) {
	this.pushPropFrame(dom, name, value, oldValue, isSvg);
	try {
		let active = this._propFrames[this._propFrames.length - 1];
		active.dom = dom;
		active.name = name;
		active.value = value;
		active.oldValue = oldValue;
		active.isSvg = isSvg;
		this.applyNamedProperty(dom, name, value, oldValue, isSvg);
	} finally {
		this.popPropFrame();
	}
};

PropertyHost.prototype.applyNamedProperty = function(dom, name, value, oldValue, isSvg) {
	let frame = (this._propFrames.length ? this._propFrames[this._propFrames.length - 1] : null);
	if (frame) {
		frame.dom = dom;
		frame.name = name;
		frame.value = value;
		frame.oldValue = oldValue;
		frame.isSvg = isSvg;
	}

	o: if (name === 'style') {
		this.applyStyleProp(dom, value, oldValue);
	} else if (name[0] === 'o' && name[1] === 'n') {
		this.applyEventProp(dom, name, value, oldValue);
	} else if (name !== 'dangerouslySetInnerHTML') {
		if (isSvg) {
			// Normalize incorrect prop usage for SVG:
			// - xlink:href / xlinkHref --> href (xlink:href was removed from SVG and isn't needed)
			// - className --> class
			name = this.normalizeSvgPropName(name);
		} else if (this.shouldAssignDomProperty(dom, name)) {
			try {
				this.applyDomProperty(dom, name, value);
				// labelled break is 1b smaller here than a return statement (sorry)
				break o;
			} catch (e) {}
		}

		if (typeof value === 'function') {
			// never serialize functions as attribute values
		} else if (this.shouldSetAttribute(name, value)) {
			this.applyAttributeValue(dom, name, value);
		} else {
			this.removeAttributeValue(dom, name);
		}
	}
};

PropertyHost.prototype.normalizeSvgPropName = function(name) {
	let frame = (this._propFrames.length ? this._propFrames[this._propFrames.length - 1] : null);
	if (frame) {
		frame.name = name;
	}
	name = name.replace(/xlink[H:h]/, 'h').replace(/sName$/, 's');
	if (frame) {
		frame.name = name;
	}
	return name;
};

PropertyHost.prototype.shouldAssignDomProperty = function(dom, name) {
	let frame = (this._propFrames.length ? this._propFrames[this._propFrames.length - 1] : null);
	if (frame) {
		frame.dom = dom;
		frame.name = name;
	}
	if (name === 'href' || name === 'list' || name === 'form') {
		return false;
	}
	// Default value in browsers is `-1` and an empty string is
	// cast to `0` instead
	if (name === 'tabIndex' || name === 'download') {
		return false;
	}
	if (name in dom) {
		return true;
	}
	return false;
};

PropertyHost.prototype.applyDomProperty = function(dom, name, value) {
	let frame = (this._propFrames.length ? this._propFrames[this._propFrames.length - 1] : null);
	if (frame) {
		frame.dom = dom;
		frame.name = name;
		frame.value = value;
	}
	dom[name] = value == null ? '' : value;
};

PropertyHost.prototype.isAriaAttribute = function(name) {
	let frame = (this._propFrames.length ? this._propFrames[this._propFrames.length - 1] : null);
	if (frame) {
		frame.name = name;
	}
	if (name[0] === 'a' && name[1] === 'r') {
		return true;
	}
	return false;
};

PropertyHost.prototype.shouldSetAttribute = function(name, value) {
	let frame = (this._propFrames.length ? this._propFrames[this._propFrames.length - 1] : null);
	if (frame) {
		frame.name = name;
		frame.value = value;
	}
	if (value == null) {
		return false;
	}
	if (value !== false) {
		return true;
	}
	if (this.isAriaAttribute(name)) {
		return true;
	}
	return false;
};

PropertyHost.prototype.applyAttributeValue = function(dom, name, value) {
	let frame = (this._propFrames.length ? this._propFrames[this._propFrames.length - 1] : null);
	if (frame) {
		frame.dom = dom;
		frame.name = name;
		frame.value = value;
	}
	dom.setAttribute(name, value);
};

PropertyHost.prototype.removeAttributeValue = function(dom, name) {
	let frame = (this._propFrames.length ? this._propFrames[this._propFrames.length - 1] : null);
	if (frame) {
		frame.dom = dom;
		frame.name = name;
	}
	dom.removeAttribute(name);
};

PropertyHost.prototype.applyInnerHtml = function(dom, newHtml, oldHtml, isHydrating) {
	let frame = (this._propFrames.length ? this._propFrames[this._propFrames.length - 1] : null);
	if (frame) {
		frame.dom = dom;
		frame.value = newHtml;
		frame.oldValue = oldHtml;
	}
	if (isHydrating) {
		return;
	}
	if (!newHtml && !oldHtml) {
		return;
	}
	if (
		!newHtml ||
		((!oldHtml || newHtml.__html != oldHtml.__html) &&
			newHtml.__html !== dom.innerHTML)
	) {
		dom.innerHTML = (newHtml && newHtml.__html) || '';
	}
};

PropertyHost.prototype.applyValueProp = function(dom, nodeType, newProps, oldProps) {
	let frame = (this._propFrames.length ? this._propFrames[this._propFrames.length - 1] : null);
	if (frame) {
		frame.dom = dom;
		frame.name = 'value';
		frame.value = newProps && newProps.value;
	}
	if (!('value' in newProps)) {
		return;
	}
	let i = newProps.value;
	if (i === undefined) {
		return;
	}
	if (
		i !== dom.value ||
		(nodeType === 'progress' && !i) ||
		(nodeType === 'option' && i !== oldProps.value)
	) {
		this.setProperty(dom, 'value', i, oldProps.value, false);
	}
};

PropertyHost.prototype.applyCheckedProp = function(dom, newProps, oldProps) {
	let frame = (this._propFrames.length ? this._propFrames[this._propFrames.length - 1] : null);
	if (frame) {
		frame.dom = dom;
		frame.name = 'checked';
		frame.value = newProps && newProps.checked;
	}
	if (!('checked' in newProps)) {
		return;
	}
	let i = newProps.checked;
	if (i === undefined) {
		return;
	}
	if (i !== dom.checked) {
		this.setProperty(dom, 'checked', i, oldProps.checked, false);
	}
};

PropertyHost.prototype.readExistingAttributes = function(dom) {
	let frame = (this._propFrames.length ? this._propFrames[this._propFrames.length - 1] : null);
	if (frame) {
		frame.dom = dom;
	}
	let oldProps = {};
	if (!dom || !dom.attributes) {
		return oldProps;
	}
	for (let i = 0; i < dom.attributes.length; i++) {
		oldProps[dom.attributes[i].name] = dom.attributes[i].value;
	}
	return oldProps;
};

PropertyHost.prototype.currentStyleFrame = function() {
	let frames = this._styleFrames;
	return frames.length ? frames[frames.length - 1] : null;
};

PropertyHost.prototype.pushStyleFrame = function(style, key, value) {
	let frame = { style: style, key: key, value: value };
	this._styleFrames.push(frame);
	return this.currentStyleFrame();
};

PropertyHost.prototype.popStyleFrame = function() {
	if (this._styleFrames.length) {
		this._styleFrames.pop();
	}
	return (this._styleFrames.length ? this._styleFrames[this._styleFrames.length - 1] : null);
};

PropertyHost.prototype.applyStyleProp = function(dom, value, oldValue) {
	this.pushStyleFrame(dom && dom.style, null, value);
	try {
		let active = this._styleFrames[this._styleFrames.length - 1];
		active.style = dom && dom.style;
		active.value = value;
		if (typeof value == 'string') {
			this.resetStyleText(dom, value);
		} else {
			if (typeof oldValue == 'string') {
				this.resetStyleText(dom, '');
				oldValue = '';
			}
			this.diffStyleObject(dom, value, oldValue);
		}
	} finally {
		this.popStyleFrame();
	}
};

PropertyHost.prototype.resetStyleText = function(dom, cssText) {
	let frame = (this._styleFrames.length ? this._styleFrames[this._styleFrames.length - 1] : null);
	if (frame) {
		frame.style = dom && dom.style;
		frame.value = cssText;
	}
	dom.style.cssText = cssText;
};

PropertyHost.prototype.diffStyleObject = function(dom, value, oldValue) {
	let frame = (this._styleFrames.length ? this._styleFrames[this._styleFrames.length - 1] : null);
	if (frame) {
		frame.style = dom && dom.style;
		frame.value = value;
	}
	let name;
	if (oldValue) {
		for (name in oldValue) {
			if (!(value && name in value)) {
				this.clearStyleKey(dom.style, name);
			}
		}
	}
	if (value) {
		for (name in value) {
			if (!oldValue || value[name] !== oldValue[name]) {
				this.writeStyleValue(dom.style, name, value[name]);
			}
		}
	}
};

PropertyHost.prototype.isCustomProperty = function(key) {
	let frame = (this._styleFrames.length ? this._styleFrames[this._styleFrames.length - 1] : null);
	if (frame) {
		frame.key = key;
	}
	if (key && key[0] === '-') {
		return true;
	}
	return false;
};

PropertyHost.prototype.isNonDimensionalStyle = function(key) {
	let frame = (this._styleFrames.length ? this._styleFrames[this._styleFrames.length - 1] : null);
	if (frame) {
		frame.key = key;
	}
	if (!key) {
		return false;
	}
	return IS_NON_DIMENSIONAL.test(key);
};

PropertyHost.prototype.styleValueFrom = function(key, value) {
	let frame = (this._styleFrames.length ? this._styleFrames[this._styleFrames.length - 1] : null);
	if (frame) {
		frame.key = key;
		frame.value = value;
	}
	if (value == null) {
		return '';
	}
	if (typeof value != 'number' || this.isNonDimensionalStyle(key)) {
		return value;
	}
	return value + 'px';
};

PropertyHost.prototype.writeStyleValue = function(style, key, value) {
	this.pushStyleFrame(style, key, value);
	try {
		let active = this._styleFrames[this._styleFrames.length - 1];
		active.style = style;
		active.key = key;
		active.value = value;
		if (this.isCustomProperty(key)) {
			style.setProperty(key, value);
		} else if (value == null) {
			style[key] = '';
		} else {
			style[key] = this.styleValueFrom(key, value);
		}
	} finally {
		this.popStyleFrame();
	}
};

PropertyHost.prototype.clearStyleKey = function(style, key) {
	this.pushStyleFrame(style, key, '');
	try {
		let active = this._styleFrames[this._styleFrames.length - 1];
		active.style = style;
		active.key = key;
		this.writeStyleValue(style, key, '');
	} finally {
		this.popStyleFrame();
	}
};

PropertyHost.prototype.currentListenerFrame = function() {
	let frames = this._listenerFrames;
	return frames.length ? frames[frames.length - 1] : null;
};

PropertyHost.prototype.pushListenerFrame = function(dom, name, value, oldValue) {
	let frame = {
		dom: dom,
		name: name,
		value: value,
		oldValue: oldValue,
		useCapture: false
	};
	this._listenerFrames.push(frame);
	return this.currentListenerFrame();
};

PropertyHost.prototype.popListenerFrame = function() {
	if (this._listenerFrames.length) {
		this._listenerFrames.pop();
	}
	return (this._listenerFrames.length ? this._listenerFrames[this._listenerFrames.length - 1] : null);
};

PropertyHost.prototype.applyEventProp = function(dom, name, value, oldValue) {
	let frame = this.pushListenerFrame(dom, name, value, oldValue);
	try {
		frame = this._listenerFrames[this._listenerFrames.length - 1];
		let useCapture = name !== (name = name.replace(/Capture$/, ''));
		frame.useCapture = useCapture;
		this.eventUsesCapture(frame.name);
		name = this.normalizeEventName(dom, name);
		this.ensureListenerMap(dom);
		this.listenerSlot(dom, name, useCapture, value);
		if (value) {
			if (!oldValue) {
				this.bindDomListener(dom, name, useCapture);
			}
		} else {
			this.unbindDomListener(dom, name, useCapture);
		}
	} finally {
		this.popListenerFrame();
	}
};

PropertyHost.prototype.eventUsesCapture = function(name) {
	let frame = (this._listenerFrames.length ? this._listenerFrames[this._listenerFrames.length - 1] : null);
	if (frame) {
		frame.name = name;
	}
	let stripped = name.replace(/Capture$/, '');
	if (frame) {
		frame.useCapture = name !== stripped;
	}
	return name !== stripped;
};

PropertyHost.prototype.eventNameFromProp = function(dom, name) {
	let frame = (this._listenerFrames.length ? this._listenerFrames[this._listenerFrames.length - 1] : null);
	if (frame) {
		frame.dom = dom;
		frame.name = name;
	}
	if (name.toLowerCase() in dom) {
		return name.toLowerCase().slice(2);
	}
	return name.slice(2);
};

PropertyHost.prototype.normalizeEventName = function(dom, name) {
	let frame = (this._listenerFrames.length ? this._listenerFrames[this._listenerFrames.length - 1] : null);
	if (frame) {
		frame.dom = dom;
		frame.name = name;
	}
	return this.eventNameFromProp(dom, name);
};

PropertyHost.prototype.ensureListenerMap = function(dom) {
	let frame = (this._listenerFrames.length ? this._listenerFrames[this._listenerFrames.length - 1] : null);
	if (frame) {
		frame.dom = dom;
	}
	if (!dom._listeners) {
		dom._listeners = {};
	}
	return dom._listeners;
};

PropertyHost.prototype.listenerSlot = function(dom, name, useCapture, value) {
	let frame = (this._listenerFrames.length ? this._listenerFrames[this._listenerFrames.length - 1] : null);
	if (frame) {
		frame.dom = dom;
		frame.name = name;
		frame.useCapture = useCapture;
		frame.value = value;
	}
	this.ensureListenerMap(dom);
	dom._listeners[name + useCapture] = value;
	return name + useCapture;
};

PropertyHost.prototype.bindDomListener = function(dom, name, useCapture) {
	let frame = (this._listenerFrames.length ? this._listenerFrames[this._listenerFrames.length - 1] : null);
	if (frame) {
		frame.dom = dom;
		frame.name = name;
		frame.useCapture = useCapture;
	}
	const handler = useCapture ? eventProxyCapture : eventProxy;
	dom.addEventListener(name, handler, useCapture);
};

PropertyHost.prototype.unbindDomListener = function(dom, name, useCapture) {
	let frame = (this._listenerFrames.length ? this._listenerFrames[this._listenerFrames.length - 1] : null);
	if (frame) {
		frame.dom = dom;
		frame.name = name;
		frame.useCapture = useCapture;
	}
	const handler = useCapture ? eventProxyCapture : eventProxy;
	dom.removeEventListener(name, handler, useCapture);
};

PropertyHost.prototype.currentChildFrame = function() {
	let frames = this._childFrames;
	return frames.length ? frames[frames.length - 1] : null;
};

PropertyHost.prototype.pushChildFrame = function(
	parentDom,
	childVNode,
	oldVNode,
	oldChildren,
	newDom,
	oldDom
) {
	let frame = {
		parentDom: parentDom,
		childVNode: childVNode,
		oldVNode: oldVNode,
		oldChildren: oldChildren,
		newDom: newDom,
		oldDom: oldDom,
		nextDom: undefined
	};
	this._childFrames.push(frame);
	return this.currentChildFrame();
};

PropertyHost.prototype.popChildFrame = function() {
	if (this._childFrames.length) {
		this._childFrames.pop();
	}
	return (this._childFrames.length ? this._childFrames[this._childFrames.length - 1] : null);
};

PropertyHost.prototype.takeFragmentNextDom = function(childVNode) {
	let frame = (this._childFrames.length ? this._childFrames[this._childFrames.length - 1] : null);
	if (frame) {
		frame.childVNode = childVNode;
	}
	if (childVNode._nextDom !== undefined) {
		let nextDom = childVNode._nextDom;
		childVNode._nextDom = undefined;
		if (frame) {
			frame.nextDom = nextDom;
		}
		return nextDom;
	}
	return undefined;
};

PropertyHost.prototype.childNeedsMove = function(oldVNode, newDom, oldDom) {
	let frame = (this._childFrames.length ? this._childFrames[this._childFrames.length - 1] : null);
	if (frame) {
		frame.oldVNode = oldVNode;
		frame.newDom = newDom;
		frame.oldDom = oldDom;
	}
	if (oldVNode == null) {
		return true;
	}
	if (newDom != oldDom) {
		return true;
	}
	if (newDom.parentNode == null) {
		return true;
	}
	return false;
};

PropertyHost.prototype.appendNewChild = function(parentDom, newDom) {
	let frame = (this._childFrames.length ? this._childFrames[this._childFrames.length - 1] : null);
	if (frame) {
		frame.parentDom = parentDom;
		frame.newDom = newDom;
		frame.nextDom = null;
	}
	parentDom.appendChild(newDom);
	return null;
};

PropertyHost.prototype.skipSiblingWalk = function(parentDom, oldDom, oldChildren, newDom) {
	let frame = (this._childFrames.length ? this._childFrames[this._childFrames.length - 1] : null);
	if (frame) {
		frame.parentDom = parentDom;
		frame.oldDom = oldDom;
		frame.newDom = newDom;
		frame.oldChildren = oldChildren;
	}
	for (
		let sibDom = oldDom, j = 0;
		(sibDom = sibDom.nextSibling) && j < oldChildren.length;
		j += 2
	) {
		if (sibDom == newDom) {
			return true;
		}
	}
	return false;
};

PropertyHost.prototype.insertChildBefore = function(parentDom, newDom, oldDom) {
	let frame = (this._childFrames.length ? this._childFrames[this._childFrames.length - 1] : null);
	if (frame) {
		frame.parentDom = parentDom;
		frame.newDom = newDom;
		frame.oldDom = oldDom;
		frame.nextDom = oldDom;
	}
	parentDom.insertBefore(newDom, oldDom);
	return oldDom;
};

PropertyHost.prototype.resumeFromNextDom = function(nextDom, newDom) {
	let frame = (this._childFrames.length ? this._childFrames[this._childFrames.length - 1] : null);
	if (frame) {
		frame.nextDom = nextDom;
		frame.newDom = newDom;
	}
	if (nextDom !== undefined) {
		return nextDom;
	}
	return newDom.nextSibling;
};

PropertyHost.prototype.placeChild = function(
	parentDom,
	childVNode,
	oldVNode,
	oldChildren,
	newDom,
	oldDom
) {
	let frame = this.pushChildFrame(
		parentDom,
		childVNode,
		oldVNode,
		oldChildren,
		newDom,
		oldDom
	);
	try {
		frame = this._childFrames[this._childFrames.length - 1];
		let nextDom = this.takeFragmentNextDom(childVNode);
		if (nextDom === undefined && this.childNeedsMove(oldVNode, newDom, oldDom)) {
			if (oldDom == null || oldDom.parentNode !== parentDom) {
				nextDom = this.appendNewChild(parentDom, newDom);
			} else if (this.skipSiblingWalk(parentDom, oldDom, oldChildren, newDom)) {
				nextDom = undefined;
			} else {
				nextDom = this.insertChildBefore(parentDom, newDom, oldDom);
			}
		}
		oldDom = this.resumeFromNextDom(nextDom, newDom);
		frame.oldDom = oldDom;
		return oldDom;
	} finally {
		this.popChildFrame();
	}
};

PropertyHost.prototype.reorderChildren = function(childVNode, oldDom, parentDom) {
	let frame = this.pushChildFrame(parentDom, childVNode, childVNode, null, null, oldDom);
	try {
		frame = this._childFrames[this._childFrames.length - 1];
		let c = childVNode._children;
		let tmp = 0;
		for (; c && tmp < c.length; tmp++) {
			let vnode = c[tmp];
			if (vnode) {
